import { describe, test, expect } from "vitest";
import { cac } from "../src/index.ts";

describe("Option alias invariants", () => {
  test("short flag -b sets all aliases to parsed value, not default", () => {
    const cli = cac();
    cli.option("-b, --base-url <url>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin", "-b", "https://gitlab.com"]);

    expect(options.b).toBe("https://gitlab.com");
    expect(options.baseUrl).toBe("https://gitlab.com");
  });

  test("long flag --base-url sets all aliases to parsed value, not default", () => {
    const cli = cac();
    cli.option("-b, --base-url <url>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin", "--base-url", "https://gitlab.com"]);

    expect(options.b).toBe("https://gitlab.com");
    expect(options.baseUrl).toBe("https://gitlab.com");
  });

  test("all aliases get default when no flag is parsed", () => {
    const cli = cac();
    cli.option("-b, --base-url <url>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin"]);

    expect(options.b).toBe("https://github.com");
    expect(options.baseUrl).toBe("https://github.com");
  });

  test("camelCase flag sets all aliases", () => {
    const cli = cac();
    cli.option("-b, --base-url <url>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin", "--baseUrl", "https://gitlab.com"]);

    expect(options.b).toBe("https://gitlab.com");
    expect(options.baseUrl).toBe("https://gitlab.com");
  });

  test("boolean option aliases are synced", () => {
    const cli = cac();
    cli.option("-v, --verbose", "Verbose output", {
      default: false,
    });
    const { options } = cli.parse(["node", "bin", "-v"]);

    expect(options.v).toBe(true);
    expect(options.verbose).toBe(true);
  });

  test("boolean option defaults to false for all aliases", () => {
    const cli = cac();
    cli.option("-v, --verbose", "Verbose output", {
      default: false,
    });
    const { options } = cli.parse(["node", "bin"]);

    expect(options.v).toBe(false);
    expect(options.verbose).toBe(false);
  });

  test("option without default - aliases still synced on parse", () => {
    const cli = cac();
    cli.option("-o, --output <path>", "Output path");
    const { options } = cli.parse(["node", "bin", "-o", "./dist"]);

    expect(options.o).toBe("./dist");
    expect(options.output).toBe("./dist");
  });

  test("multiple options with aliases are all synced correctly", () => {
    const cli = cac();
    cli.option("-b, --base-url <url>", "Base URL", {
      default: "https://github.com",
    });
    cli.option("-o, --output <path>", "Output path", {
      default: "./dist",
    });
    const { options } = cli.parse([
      "node", "bin", 
      "--base-url", "https://gitlab.com",
      "-o", "./build"
    ]);

